\begin{abstract}
We develop a self-contained quantitative theory of non-homogeneous (shifted) quadratic Diophantine problems $Q(x-t) = c$ with $x \in \Z^n$, where $Q(x) = \sum_{i,j} A_{ij} x_i x_j$ is a real quadratic form and $t \in \R^n$ a fixed shift. The only structural hypothesis is a \emph{spectral sandwich}: $m\|x\|^2 \le Q(x) \le M\|x\|^2$ for all $x \in \R^n$, which for symmetric $A$ is equivalent to all eigenvalues lying in $[m,M]$. We prove a spectral gap $Q(x-t) \ge m\, d(t,\Z^n)^2$ valid for all integer points, hence a Diophantine obstruction excluding every target below the gap; an effective gap $m/q^2$ for rational shifts of denominator $q$; a matching covering bound $\min_x Q(x-t) \le Mn/4$ by coordinatewise rounding, yielding the sandwich $m\,d(t,\Z^n)^2 \le \mu(Q,t) \le Mn/4$ for the inhomogeneous minimum; two-sided counting estimates $\bigl(2\sqrt{R/(Mn)}-1\bigr)^n \le N(R) \le \bigl(2\sqrt{R/m}+1\bigr)^n$ beyond the covering threshold, so $N(R) \asymp R^{n/2}$; convergence, diagonal factorisation, an explicit lower bound and gap-rate exponential decay for the inhomogeneous theta series $\Theta(s) = \sum_{x \in \Z^n} e^{-sQ(x-t)}$, with $\Theta(s) \to 0$ whenever the shift is off the lattice; and a complete determination of the extremal set for the half-shifted sum of squares: $\sum_i (x_i - \tfrac12)^2 \ge n/4$, with equality exactly on the $2^n$ vertices of the unit cube. All constants are explicit in $m$, $M$, $n$ and the denominator of the shift.
\end{abstract}

\noindent\textbf{Keywords:} non-homogeneous quadratic form, inhomogeneous minimum, spectral gap, lattice reduction, covering radius, theta series, Diophantine obstruction, representation numbers.

\section{Introduction}

\subsection{The problem}

Classical Diophantine theory of quadratic forms concerns the \emph{homogeneous} equation $Q(x) = c$ with $x \in \Z^n$. The \emph{non-homogeneous}, or \emph{shifted}, problem
\[
Q(x - t) = c, \qquad x \in \Z^n, \quad t \in \R^n \text{ fixed},
\]
behaves differently. It has no trivial solution: the point $x = 0$ carries no privilege once the form is recentred at $t$. Congruence obstructions weaken or disappear when $t$ is irrational. The fundamental invariant becomes a geometric one, the \emph{inhomogeneous minimum}
\[
\mu(Q,t) \;=\; \inf_{x \in \Z^n} Q(x-t),
\]
the squared radius of the smallest $Q$-ellipsoid centred at $t$ meeting $\Z^n$. Supremising over $t$ recovers the squared covering radius of the lattice in the geometry of $Q$. This invariant is central to lattice-based cryptography (the closest vector problem), to coset codes over $\Z$, and to lattice partition functions in statistical mechanics.

\subsection{Hypothesis and scope}

We work under a single hypothesis abstracting away everything about $A$ except its extremes of stretching. Every bound depends only on the pair $(m,M)$, the dimension $n$, and the arithmetic of the shift, and every constant is explicit. The contribution is the systematic assembly: gap, covering, counting and theta behaviour all follow from one elementary lattice-reduction estimate, and each is sharp in the model case of the half-shifted sum of squares, where all inequalities collapse to equalities and the extremal set is determined exactly.

\section{Definitions}

Throughout $n \ge 0$ is an integer and indices run over $\{1,\dots,n\}$.

\begin{definition}[Squared norm]
For $x \in \R^n$, $\|x\|^2 = \sum_{i=1}^n x_i^2$.
\end{definition}

\begin{definition}[Quadratic form of a matrix]
For a real $n\times n$ matrix $A$, $Q_A(x) = \sum_{i=1}^n\sum_{j=1}^n A_{ij} x_i x_j$. Only the symmetric part of $A$ affects $Q_A$.
\end{definition}

\begin{definition}[Spectral bounds]
$A$ \emph{has spectral bounds} $m, M \in \R$ if
\[
m\|x\|^2 \;\le\; Q_A(x) \;\le\; M\|x\|^2 \qquad \text{for all } x \in \R^n.
\]
For symmetric $A$ this holds precisely when all eigenvalues of $A$ lie in $[m,M]$, by Rayleigh's principle.
\end{definition}

\begin{definition}[Non-homogeneous evaluation]
For $t \in \R^n$ and $x \in \Z^n$ we write $Q(x-t) = Q_A\bigl((x_i - t_i)_i\bigr)$.
\end{definition}

\begin{definition}[Distance to the integers]
For $u \in \R$, $\dZ(u) = \min(\{u\},\, 1 - \{u\})$, where $\{u\} = u - \lfloor u\rfloor$. Then $0 \le \dZ(u) \le \tfrac12$, and $\dZ(u) = 0$ iff $u \in \Z$. For $t \in \R^n$,
\[
d(t,\Z^n)^2 \;=\; \sum_{i=1}^n \dZ(t_i)^2 .
\]
\end{definition}

\begin{definition}[Inhomogeneous minimum and theta series]
$\mu(Q,t) = \inf_{x \in \Z^n} Q(x-t)$, and for $s>0$,
\[
\Theta(s) \;=\; \sum_{x \in \Z^n} \exp\bigl(-s\,Q(x-t)\bigr),
\]
whenever the family is summable (Theorem~\ref{thm:conv}).
\end{definition}

\begin{example}[Diagonal forms]\label{ex:diag}
If $A = \operatorname{diag}(d_1,\dots,d_n)$ then $Q_A(x) = \sum_i d_i x_i^2$, and if $m \le d_i \le M$ for all $i$, then $A$ has spectral bounds $m, M$ (compare termwise and sum). The identity matrix gives the sum of squares with $m = M = 1$.
\end{example}

\section{Lattice reduction and the spectral gap}

\begin{lemma}[Nearest-integer estimate]\label{lem:near}
For all $u \in \R$ and $k \in \Z$, $\dZ(u) \le |u - k|$.
\end{lemma}

\begin{proof}
Write $u = \lfloor u\rfloor + \{u\}$. If $k \le \lfloor u \rfloor$ then $u - k \ge \{u\} \ge \dZ(u) \ge 0$. If $k \ge \lfloor u\rfloor + 1$ then $k - u \ge 1 - \{u\} \ge \dZ(u) \ge 0$. In both cases $|u-k| \ge \dZ(u)$.
\end{proof}

\begin{corollary}\label{cor:sq}
$\dZ(u)^2 \le (u-k)^2$ for $u \in \R$, $k \in \Z$; consequently $d(t,\Z^n)^2 \le \|x - t\|^2$ for all $t \in \R^n$, $x \in \Z^n$.
\end{corollary}

\begin{proof}
Square Lemma~\ref{lem:near}, both sides being nonnegative, and sum over coordinates.
\end{proof}

\begin{lemma}[Positivity off the lattice]\label{lem:pos}
If $\{u\} \ne 0$ then $\dZ(u) > 0$. Hence if some coordinate $t_i$ is non-integral then $d(t,\Z^n)^2 > 0$.
\end{lemma}

\begin{proof}
$0 < \{u\} < 1$ forces $\{u\}>0$ and $1-\{u\}>0$. The sum $\sum_i \dZ(t_i)^2$ has nonnegative terms and one strictly positive term.
\end{proof}

\begin{theorem}[Spectral gap lower bound]\label{thm:gap}
Let $A$ have spectral bounds $m, M$ with $m \ge 0$ and let $t \in \R^n$. Then for every $x \in \Z^n$,
\[
Q(x-t) \;\ge\; m\, d(t,\Z^n)^2 .
\]
\end{theorem}

\begin{proof}
By Corollary~\ref{cor:sq} and $m \ge 0$ we have $m\,d(t,\Z^n)^2 \le m\|x-t\|^2$, and the lower spectral bound applied to the vector $x - t$ gives $m\|x-t\|^2 \le Q(x-t)$.
\end{proof}

\begin{theorem}[Strict positivity]\label{thm:strict}
If in addition $m > 0$ and some coordinate of $t$ is non-integral, then $Q(x-t) > 0$ for every $x \in \Z^n$.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:gap} with Lemma~\ref{lem:pos}.
\end{proof}

\begin{theorem}[Diophantine obstruction]\label{thm:obstruction}
Under the hypotheses of Theorem~\ref{thm:gap}, if $c < m\,d(t,\Z^n)^2$ then $Q(x-t) = c$ has no solution $x \in \Z^n$.
\end{theorem}

\begin{proof}
A solution would give $c = Q(x-t) \ge m\,d(t,\Z^n)^2 > c$, a contradiction.
\end{proof}

We call $[0,\, m\,d(t,\Z^n)^2)$ the \emph{forbidden zone} of the pair $(Q,t)$: a purely geometric obstruction requiring no congruence input, and persisting for irrational shifts.

\begin{theorem}[Half-integral shift]\label{thm:half}
If $\{t_i\} = \tfrac12$ for every $i$, then $d(t,\Z^n)^2 = n/4$, and hence $Q(x-t) \ge mn/4$ for every $x \in \Z^n$.
\end{theorem}

\begin{proof}
$\dZ(t_i) = \min(\tfrac12,\tfrac12) = \tfrac12$, so $d(t,\Z^n)^2 = n/4$; apply Theorem~\ref{thm:gap}.
\end{proof}

\begin{corollary}[Half-shifted sum of squares]\label{cor:halfsos}
For every $x \in \Z^n$, $\sum_{i=1}^n (x_i - \tfrac12)^2 \ge n/4$; consequently the equation $\sum_i (x_i - \tfrac12)^2 = c$ has no integer solution for $c < n/4$.
\end{corollary}

\begin{proof}
Apply Theorem~\ref{thm:half} to $A = I$ (spectral bounds $m = M = 1$ by Example~\ref{ex:diag}) and $t = (\tfrac12,\dots,\tfrac12)$.
\end{proof}

\subsection{Effective gaps at rational shifts}

\begin{lemma}[Denominator bound]\label{lem:denom}
Let $a, q \in \Z$ with $q > 0$ and $q \nmid a$. Then $\dZ(a/q) \ge 1/q$.
\end{lemma}

\begin{proof}
Let $L = \lfloor a/q\rfloor$ and $r = a - qL$, so $\{a/q\} = r/q$ with $0 \le r < q$, and $r \ne 0$ since $q \nmid a$. Hence $1 \le r \le q-1$, so $\{a/q\} = r/q \ge 1/q$ and $1 - \{a/q\} = (q-r)/q \ge 1/q$; the minimum is at least $1/q$.
\end{proof}

\begin{theorem}[Effective spectral gap at a rational shift]\label{thm:rational}
Let $A$ have spectral bounds $m \ge 0$, $M$; let $q \in \Z_{>0}$ and $t_i = a_i/q$ with $a_i \in \Z$. If $q \nmid a_{i_0}$ for some index $i_0$, then $Q(x-t) \ge m/q^2$ for every $x \in \Z^n$. Consequently $Q(x-t) = c$ has no integer solution for $c < m/q^2$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:denom}, $\dZ(t_{i_0})^2 \ge 1/q^2$, and $d(t,\Z^n)^2 \ge \dZ(t_{i_0})^2$ since the omitted terms are nonnegative. Multiply by $m \ge 0$ and apply Theorem~\ref{thm:gap}.
\end{proof}

\section{Covering: the matching upper bound}

\begin{theorem}[Rounding / covering bound]\label{thm:cover}
Let $A$ have spectral bounds $m$, $M$ with $M \ge 0$ and let $t \in \R^n$. Then there exists $x_0 \in \Z^n$ with $Q(x_0 - t) \le Mn/4$.
\end{theorem}

\begin{proof}
Take $x_0 = (\round(t_i))_i$. Then $|t_i - \round(t_i)| \le \tfrac12$ for each $i$, so $\|x_0 - t\|^2 \le n/4$, and the upper spectral bound gives $Q(x_0-t) \le M\|x_0-t\|^2 \le Mn/4$.
\end{proof}

\begin{theorem}[Spectral sandwich for the inhomogeneous minimum]\label{thm:sandwich}
Let $A$ have spectral bounds $m \ge 0$, $M \ge 0$, and let $t \in \R^n$. Then
\[
m\,d(t,\Z^n)^2 \;\le\; \mu(Q,t) \;\le\; \frac{Mn}{4}.
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:gap} the set $\{Q(x-t): x\in\Z^n\}$ is bounded below by $m\,d(t,\Z^n)^2$, so the infimum exists and is at least that value; by Theorem~\ref{thm:cover} it is at most $Mn/4$.
\end{proof}

\begin{remark}[Sharpness]
For $A = I$ and $t$ half-integral we have $m = M = 1$ and $d(t,\Z^n)^2 = n/4$, so both sides equal $n/4$ and $\mu = n/4$ exactly. In general the two ends differ by the factor $(M/m)\cdot n/\bigl(4\,d(t,\Z^n)^2\bigr) \ge M/m$: the sandwich is tightest for well-conditioned forms and shifts near a deep hole.
\end{remark}

\begin{theorem}[Solvability window]\label{thm:window}
Let $A$ have spectral bounds $m \ge 0$, $M \ge 0$. Then for every $R \ge Mn/4$ there exists $x \in \Z^n$ with $Q(x-t) \le R$; and for every $R < m\,d(t,\Z^n)^2$ there is no such $x$.
\end{theorem}

\begin{proof}
The first assertion is Theorem~\ref{thm:cover} with transitivity, the second Theorem~\ref{thm:gap} with transitivity.
\end{proof}

Thus $[m\,d(t,\Z^n)^2,\, Mn/4]$ is the \emph{undetermined band}: outside it solvability is decided by the two constants alone.

\section{Counting integer solutions}

Write $N(R) = \#\{x \in \Z^n : Q(x-t) \le R\}$.

\begin{lemma}[Coordinatewise localisation]\label{lem:loc}
Let $A$ have spectral bounds $m > 0$, $M$. If $Q(x-t) \le R$ then $|x_i - t_i| \le \sqrt{R/m}$ for every $i$.
\end{lemma}

\begin{proof}
$m\|x-t\|^2 \le Q(x-t) \le R$ gives $\|x-t\|^2 \le R/m$; the single term $(x_i-t_i)^2$ of that nonnegative sum is therefore at most $R/m$.
\end{proof}

\begin{theorem}[Counting upper bound]\label{thm:countup}
Let $A$ have spectral bounds $m > 0$, $M$. Any finite set $S \subseteq \Z^n$ of solutions of $Q(x-t)\le R$ satisfies
\[
\# S \;\le\; \Bigl(2\sqrt{R/m} + 1\Bigr)^{n}.
\]
In particular $N(R) \le (2\sqrt{R/m}+1)^n$: representation numbers grow at most polynomially in $\sqrt R$.
\end{theorem}

\begin{proof}
Put $r = \sqrt{R/m}$. By Lemma~\ref{lem:loc}, $S \subseteq \prod_i \bigl(\Z \cap [t_i - r, t_i + r]\bigr)$. The $i$-th factor is $\{\lceil t_i - r\rceil,\dots,\lfloor t_i + r\rfloor\}$, of cardinality $\max(0, \lfloor t_i+r\rfloor + 1 - \lceil t_i - r\rceil)$, which is at most $2r+1$ because $\lfloor t_i+r\rfloor \le t_i + r$ and $\lceil t_i - r\rceil \ge t_i - r$. Multiply the $n$ factors.
\end{proof}

\begin{theorem}[Counting lower bound above the covering threshold]\label{thm:countlow}
Let $A$ have spectral bounds $m$, $M$ with $M > 0$, let $n \ge 1$ and $R \ge Mn/4$. Then there is a finite set $S$ of integer solutions of $Q(x-t) \le R$ with
\[
\#S \;\ge\; \Bigl(2\sqrt{R/(Mn)} - 1\Bigr)^{n}.
\]
\end{theorem}

\begin{proof}
Put $p = \sqrt{R/(Mn)}$; the hypothesis gives $p \ge \tfrac12$, so $2p-1 \ge 0$. Let $S = \prod_i \bigl(\Z\cap[t_i-p, t_i+p]\bigr)$. For $x \in S$, $(x_i-t_i)^2 \le p^2$ for each $i$, so $\|x-t\|^2 \le np^2 = R/M$ and hence $Q(x-t) \le M\|x-t\|^2 \le R$. Each factor has cardinality $\lfloor t_i+p\rfloor + 1 - \lceil t_i-p\rceil \ge 2p-1$; multiply $n$ nonnegative factors.
\end{proof}

\begin{theorem}[Two-sided counting]\label{thm:count2}
Let $A$ have spectral bounds $m>0$, $M>0$, let $n\ge1$ and $R \ge Mn/4$. Then there is a finite set $S$ of integer solutions of $Q(x-t)\le R$ with
\[
\Bigl(2\sqrt{R/(Mn)}-1\Bigr)^{n} \;\le\; \#S \;\le\; \Bigl(2\sqrt{R/m}+1\Bigr)^{n}.
\]
Consequently $N(R) \asymp R^{n/2}$, with constants depending only on $m$, $M$ and $n$.
\end{theorem}

\begin{proof}
Take $S$ from Theorem~\ref{thm:countlow} and apply Theorem~\ref{thm:countup} to it.
\end{proof}

The exponent $n/2$ is the volume-heuristic order, the region $\{Q(y)\le R\}$ being an ellipsoid of volume proportional to $R^{n/2}$; what is gained is that the constants are explicit and require no regularity or symmetry of $A$.

\section{The inhomogeneous theta series}

\begin{lemma}[One-dimensional Gaussian sums]\label{lem:gauss}
For $c>0$ and $a \in \R$, the family $\bigl(e^{-c(k-a)^2}\bigr)_{k\in\Z}$ is summable.
\end{lemma}

\begin{proof}
For $k \in \N$, the elementary inequality $(k-a)^2 \ge k - \tfrac{(2a+1)^2}{4}$ (equivalent, after expansion, to $\bigl(k - \tfrac{2a+1}{2}\bigr)^2 \ge 0$) gives $e^{-c(k-a)^2} \le e^{c(2a+1)^2/4} e^{-ck}$, a convergent geometric series. The sum over negative integers is the same statement with $a$ replaced by $-a$.
\end{proof}

\begin{theorem}[Convergence of the inhomogeneous theta series]\label{thm:conv}
Let $A$ have spectral bounds $m>0$, $M$, let $t \in \R^n$ and $s>0$. Then $\bigl(e^{-sQ(x-t)}\bigr)_{x\in\Z^n}$ is summable, so $\Theta(s)$ is well defined and positive.
\end{theorem}

\begin{proof}
By the lower spectral bound $Q(x-t)\ge m\|x-t\|^2$, hence
\[
e^{-sQ(x-t)} \;\le\; e^{-sm\|x-t\|^2} \;=\; \prod_{i=1}^n e^{-sm(x_i-t_i)^2}.
\]
Each one-dimensional factor is summable over $\Z$ by Lemma~\ref{lem:gauss} with $c = sm>0$, and a product of $n$ nonnegative summable families is summable over $\Z^n$ (induction on $n$, splitting $\Z^{n+1}\cong \Z\times\Z^n$ and using Fubini--Tonelli for nonnegative families). Domination concludes.
\end{proof}

\begin{theorem}[Lower bound from covering]\label{thm:thetalow}
Let $A$ have spectral bounds $m>0$, $M\ge0$ and let $s>0$. Then $\Theta(s) \ge \exp(-sMn/4)$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:cover} there is $x_0$ with $Q(x_0-t)\le Mn/4$, so the single term $e^{-sQ(x_0-t)}$ is at least $e^{-sMn/4}$; all remaining terms are positive.
\end{proof}

\begin{theorem}[Exponential decay at the gap rate]\label{thm:decay}
Let $A$ have spectral bounds $m>0$, $M$, and let $0 < s_0 \le s$. Then
\[
\Theta(s) \;\le\; \exp\bigl(-(s-s_0)\, m\, d(t,\Z^n)^2\bigr)\,\Theta(s_0).
\]
\end{theorem}

\begin{proof}
Write $g = m\,d(t,\Z^n)^2$. For each $x \in \Z^n$, Theorem~\ref{thm:gap} gives $Q(x-t)\ge g$, and since $s-s_0\ge0$,
\[
-sQ(x-t) = -(s-s_0)Q(x-t) - s_0 Q(x-t) \le -(s-s_0)g - s_0 Q(x-t).
\]
Exponentiate, sum over $x$ (both families summable by Theorem~\ref{thm:conv}), and pull out the constant.
\end{proof}

\begin{corollary}[Decay to zero]\label{cor:tozero}
If $m>0$ and some coordinate of $t$ is non-integral, then $\Theta(s)\to0$ as $s\to\infty$.
\end{corollary}

\begin{proof}
By Lemma~\ref{lem:pos} the gap $g = m\,d(t,\Z^n)^2$ is positive. With $s_0 = 1$ in Theorem~\ref{thm:decay}, $0 \le \Theta(s) \le e^{-(s-1)g}\Theta(1) \to 0$; squeeze.
\end{proof}

This is the analytic shadow of Theorem~\ref{thm:strict}: $\Theta(s)\to0$ says exactly that no lattice point sits at zero energy. When $t \in \Z^n$, by contrast, the term $x=t$ contributes $1$ for all $s$ and $\Theta(s)\to1$. Combining Theorems~\ref{thm:thetalow} and~\ref{thm:decay},
\[
m\,d(t,\Z^n)^2 \;\le\; \liminf_{s\to\infty}\frac{-\log\Theta(s)}{s} \;\le\; \limsup_{s\to\infty}\frac{-\log\Theta(s)}{s}\;\le\;\frac{Mn}{4},
\]
so the decay rate obeys the same sandwich as $\mu(Q,t)$.

\begin{theorem}[Diagonal factorisation]\label{thm:factor}
Let $A = \operatorname{diag}(d_1,\dots,d_n)$ with all $d_i>0$, let $t\in\R^n$ and $s>0$. Then
\[
\Theta(s) \;=\; \prod_{i=1}^{n}\ \sum_{k\in\Z} \exp\bigl(-s d_i (k - t_i)^2\bigr),
\]
an $n$-fold product of one-dimensional shifted Jacobi theta values.
\end{theorem}

\begin{proof}
For diagonal $A$, $Q(x-t) = \sum_i d_i(x_i-t_i)^2$, so each summand factors as $\prod_i e^{-sd_i(x_i-t_i)^2}$. Each factor family is summable over $\Z$ (Lemma~\ref{lem:gauss} with $c = sd_i>0$) and nonnegative, so the sum over $\Z^n$ of the product equals the product of the sums, by induction on $n$ with Fubini--Tonelli at each step.
\end{proof}

\section{Extremal structure: the half-shifted sum of squares}

Take $A=I$ and $t=(\tfrac12,\dots,\tfrac12)$, so $Q(x-t) = \sum_i (x_i-\tfrac12)^2$, $m=M=1$, and the sandwich is exact: $\mu = n/4$.

\begin{lemma}[One-coordinate extremality]\label{lem:onecoord}
For every $k\in\Z$, $(k-\tfrac12)^2 \ge \tfrac14$, with equality if and only if $k \in \{0,1\}$.
\end{lemma}

\begin{proof}
$(k-\tfrac12)^2 - \tfrac14 = k^2 - k = k(k-1)$, a product of consecutive integers, hence nonnegative, and zero exactly for $k = 0$ or $k = 1$.
\end{proof}

\begin{theorem}[Exact extremal set]\label{thm:extremal}
For $x\in\Z^n$,
\[
\sum_{i=1}^n\Bigl(x_i-\tfrac12\Bigr)^2 \;\le\; \frac n4
\qquad\Longleftrightarrow\qquad
x_i \in \{0,1\} \text{ for every } i .
\]
\end{theorem}

\begin{proof}
If every $x_i \in \{0,1\}$ then each term equals $\tfrac14$ by Lemma~\ref{lem:onecoord} and the sum is $n/4$. Conversely, each term is at least $\tfrac14$; if the total is at most $n/4$ then it equals $n/4$, and a sum of terms each bounded below by a fixed value, equal to the sum of those bounds, forces every term to equal $\tfrac14$; equality in Lemma~\ref{lem:onecoord} then forces $x_i \in\{0,1\}$.
\end{proof}

\begin{theorem}[Multiplicity of the minimum]\label{thm:mult}
The set of $x \in \Z^n$ with $\sum_i (x_i-\tfrac12)^2 \le n/4$ equals $\{0,1\}^n$, the vertex set of the unit cube, and has cardinality exactly $2^n$.
\end{theorem}

\begin{proof}
Immediate from Theorem~\ref{thm:extremal}: the solution set is a product of $n$ copies of $\{0,1\}$.
\end{proof}

So the inhomogeneous minimum $n/4$ is attained with exponential multiplicity $2^n$. At $R = n/4$, Theorem~\ref{thm:countup} gives the upper bound $(\sqrt n + 1)^n$, larger than the truth $2^n$ but of the same exponential type in $n$; Theorem~\ref{thm:mult} gives the exact answer and thereby calibrates the loss in the soft bounds.

\section{Algorithms}

\paragraph{Gap certificate.} Given $A$, a spectral lower bound $m>0$, a shift $t$ and a target $c$, compute $g = m\sum_i \dZ(t_i)^2$; if $c<g$, report unsolvability (Theorem~\ref{thm:obstruction}), otherwise report inconclusive. Cost $O(n)$ once $m$ is known; obtaining $m$ for symmetric $A$ costs one smallest-eigenvalue computation, $O(n^3)$ by dense methods. For rational $t$ with common denominator $q$ the certified value $g = m/q^2$ (Theorem~\ref{thm:rational}) removes all floating point from the arithmetic step.

\paragraph{Rounding solver and sandwich report.} Set $x_0 = \round(t)$ coordinatewise, evaluate $Q(x_0-t)$ in $O(n^2)$ operations, and report that $\mu(Q,t)$ lies in $\bigl[m\,d(t,\Z^n)^2,\ \min\bigl(Q(x_0-t),\,Mn/4\bigr)\bigr]$.

\paragraph{Certified exhaustive enumeration.} All solutions of $Q(x-t)\le R$ lie in the box $\prod_i[\lceil t_i - r\rceil, \lfloor t_i+r\rfloor]$ with $r=\sqrt{R/m}$ (Lemma~\ref{lem:loc}); enumerate and filter. The box holds at most $(2r+1)^n$ points, so the cost is $O\bigl(n^2 (2\sqrt{R/m}+1)^n\bigr)$: exponential in $n$, as expected for a closest-vector-type problem, but with a fully certified search region. Depth-first traversal with partial-sum pruning visits far fewer nodes, and for diagonal $A$ the pruning is exact.

\section{Applications}

\paragraph{Diophantine non-solvability certificates.} Theorems~\ref{thm:obstruction} and~\ref{thm:rational} give one-line unsolvability proofs for shifted quadratic equations to which congruence methods do not apply. For instance $2x_1^2+3x_2^2+5x_3^2$ evaluated at $x - (\tfrac13,\tfrac13,\tfrac13)$ has $m=2$, $M=5$ and denominator $q=3$, so the value is always at least $2/9$, and the sharper real bound gives $2\cdot3\cdot(1/3)^2 = 2/3$.

\paragraph{Lattice cryptography.} With $Q$ the Gram form of a lattice basis, $\mu(Q,t)$ is the squared distance from $t$ to the lattice, i.e.\ the objective of the closest vector problem. Theorem~\ref{thm:sandwich} is a certified two-sided estimate: the covering side guarantees that decoding always succeeds within radius $\sqrt{Mn}/2$, while the gap side is a lower bound on the achievable decoding distance and hence a security floor: a ciphertext perturbed by less than half that distance is uniquely decodable. Theorem~\ref{thm:count2} quantifies how fast the number of candidate decodings explodes with the search radius, the complexity driver of enumeration attacks.

\paragraph{Coset codes over $\Z$.} For an integer code with quadratic energy $Q$ and coset representative $t$, the gap is the minimum coset energy, a minimum-distance guarantee; Theorem~\ref{thm:mult} exhibits the binary cube as the extremal coset of the sum-of-squares code.

\paragraph{Statistical mechanics.} $\Theta(s)$ is the canonical partition function of a lattice system with energy $Q(x-t)$ at inverse temperature $s$. Theorem~\ref{thm:decay} bounds the free energy per unit inverse temperature below by the gap and Theorem~\ref{thm:thetalow} bounds it above by the covering value; Theorem~\ref{thm:mult} identifies a $2^n$-fold degenerate ground state, a residual entropy of $n\log 2$.

\paragraph{Integer quadratic programming.} Theorem~\ref{thm:window} is a certified feasibility test for $Q(x-t)\le R$: reject below the gap, accept above the covering threshold with the rounded point as witness, and branch only inside the undetermined band.

\section{Discussion and open problems}

The gap bound of Theorem~\ref{thm:gap} is sharp whenever the minimising integer point realises coordinatewise nearest-integer rounding and the form attains its lower spectral bound on the resulting displacement; for $A=I$ this always occurs. The covering bound $Mn/4$ is by contrast generally lossy, replacing every eigenvalue by the largest.

\begin{conjecture}[Sharp covering constant]\label{conj:trace}
For every symmetric positive definite $A$ with spectral bounds $m$, $M$ and every shift $t$,
\[
\mu(Q,t) \;\le\; \tfrac14 \tr(A),
\]
with equality if and only if $A$ is diagonal and $t$ is a half-integral shift. In particular $\mu \le Mn/4$ is never sharp unless all eigenvalues coincide.
\end{conjecture}

The key insight is that the rounding point $x = \round(t)$ used in Theorem~\ref{thm:cover} wastes information: it bounds $Q(x-t)$ by $\lambda_{\max}\|x-t\|^2$, whereas expanding $Q(x-t) = \sum_{i,j} A_{ij}(x_i-t_i)(x_j-t_j)$ and averaging over a random $\pm\tfrac12$ displacement gives expectation exactly $\tr(A)/4$, the off-diagonal terms cancelling in mean. The averaging argument needs only the finite probability space $\{\pm\tfrac12\}^n$.

\begin{conjecture}[Gap--theta duality]\label{conj:duality}
For a spectrally sandwiched form with $m>0$,
\[
\lim_{s\to\infty} -\frac1s \log \Theta(s) \;=\; \mu(Q,t),
\]
and moreover $\Theta(s)\,e^{s\mu(Q,t)} \to r(\mu)$, the number of integer points attaining the minimum (finite by Theorem~\ref{thm:countup}).
\end{conjecture}

Theorem~\ref{thm:decay} proves one inequality purely from a termwise bound; the matching upper bound must come from isolating the minimising terms and dominating the rest by the counting estimate. In this sense counting and decay are two halves of a single Laplace-method statement. For the half-shifted sum of squares the conjecture follows from Theorems~\ref{thm:factor} and~\ref{thm:mult}, with $r(\mu) = 2^n$.

Further directions include anisotropic (ellipsoidal) enumeration regions sharpening the counting constants to the true volume ratio; the study of $\sup_t \mu(Q,t)$, the squared covering radius, which the sandwich pins to within the condition number; modular refinements combining the denominator gap $m/q^2$ with congruence conditions modulo $q$ inside the undetermined band; and signed variants for indefinite forms, where the lower bound argument uses only $Q \ge m\|\cdot\|^2$ and the ``gap'' becomes a bound on how negative $Q(x-t)$ can be.

